namespace Unity.Mathematics {
 public struct float2 { public float x,y; public float2(float x,float y){this.x=x;this.y=y;} public static float2 zero=>new float2(); public static float2 operator +(float2 a,float2 b)=>new float2(a.x+b.x,a.y+b.y);public static float2 operator -(float2 a,float2 b)=>new float2(a.x-b.x,a.y-b.y);public static float2 operator -(float2 a)=>new float2(-a.x,-a.y);public static float2 operator *(float2 a,float b)=>new float2(a.x*b,a.y*b);public static float2 operator /(float2 a,float b)=>new float2(a.x/b,a.y/b);}
 public struct int2 {public static bool operator ==(int2 a,int2 b)=>a.x==b.x&&a.y==b.y;public static bool operator !=(int2 a,int2 b)=>!(a==b);public override bool Equals(object o)=>o is int2 x&&x==this;public override int GetHashCode()=>System.HashCode.Combine(x,y); public int x,y;public int2(int x,int y){this.x=x;this.y=y;} }
 public struct float3 {public static float3 zero=>default;public float x,y,z;public float3(float x,float y,float z){this.x=x;this.y=y;this.z=z;}public float2 xz=>new float2(x,z);}
 public static class math {public static float length(float2 a)=>System.MathF.Sqrt(lengthsq(a));public static float lengthsq(float2 a)=>a.x*a.x+a.y*a.y;public static float distance(float2 a,float2 b)=>length(a-b);public static float2 normalize(float2 a)=>a/length(a);public static float dot(float2 a,float2 b)=>a.x*b.x+a.y*b.y;public static float min(float a,float b)=>System.MathF.Min(a,b);public static float max(float a,float b)=>System.MathF.Max(a,b);public static float round(float a)=>System.MathF.Round(a);public static float2 lerp(float2 a,float2 b,float t)=>a+(b-a)*t;public static float ceil(float x)=>System.MathF.Ceiling(x);public static bool all(bool x)=>x;}
}
public struct BodyInput { public Unity.Mathematics.float2 move,face,point; public int slot; public bool aim,hasPoint,primary,secondary; }
